  let duration=number(d.durationSeconds); if(duration===null||duration<6||duration>600){duration=30;missing.push('durationSeconds: proposta DEMO 30 secondi da confermare');}
  const lengths=[Math.min(3,duration/6),...Array(4).fill((duration-Math.min(3,duration/6))/5)];lengths.push(duration-lengths.reduce((a,b)=>a+b,0));
  let cursor=0;const labels=['Hook','Problema del pubblico','Processo','Dimostrazione','Prova autorizzata','Invito all’azione'];
  const visuals=['Primo piano sul risultato da spiegare, senza prometterlo','Dettaglio della situazione iniziale','Mani e passaggi del lavoro','Confronto visivo sul processo','Materiale reale approvato dal cliente','Logo e contatto fornito'];
  const copy=[c.value('message'),`Per ${c.value('audience')}: quale difficoltà affrontiamo?`,'Mostriamo come lavoriamo, un passaggio alla volta.',c.value('offer','Dettaglio del servizio da confermare'),'Inserire soltanto una prova con fonte e permesso.',c.value('cta')];
