  return {title:`Storyboard · ${c.name}`,service:'video',summary:'Sei scene con tempi e istruzioni di ripresa; proposta DEMO, nessun video generato.',sections:[...scenes,section('Montaggio e materiali',`Formato: ${c.value('format')}. Sottotitoli proposti in blocchi di 3–4 parole, safe area da controllare sul formato. Asset forniti: ${list(d.assets).length}. Taglio master → adattamenti → controllo voce/musica → revisione.`)],metrics:{proposedDurationSeconds:duration,sceneCount:6},missingInputs:[...missing,...(!list(d.assets).length?['assets con fonte e diritti']:[])]};
