function napFindings(canonical,listings,prefix='') {
  const findings=[];for(const l of listings)for(const field of ['name','address','phone','hours']){const expected=text(canonical[field]),actual=text(l[field]);if(expected&&normal(expected)!==normal(actual))findings.push(finding(`nap-${field}`,`${prefix}${text(l.source)||'fonte senza nome'}`,`${field}: trovato “${actual||'[mancante]'}”; proporre “${expected}”, previa conferma del titolare.`));}return findings;
}

