  return {title:`Coerenza locale e post GBP · ${c.name}`,service:'local',summary:`Confrontate ${listings.length} fonti fornite con la scheda canonica DEMO.`,sections:[section('Proposte di correzione',rows(findings.map(f=>`${f.subject}: ${f.detail}`))),section('Scheda canonica da confermare',rows(['name','address','phone','hours'].map(k=>`${k}: ${display(canonical[k])}`))),section('Bozza post locale',`${c.name}: ${c.value('offer','scopri i servizi della nostra attività')}. ${cleanList(c.data.services).join(', ')}. Zona: ${c.value('zone')}. ${c.value('cta','Contattaci per informazioni')}. Verificare orari e materiali prima dell’approvazione.`),section('Prossimo controllo','Verificare manualmente la proprietà delle schede; approvare ogni correzione; confrontare il dato dopo l’intervento. Nessuna promessa di posizionamento e nessuna modifica effettuata.')],findings,metrics:{sourcesCompared:listings.length,discrepancies:findings.length,localRank:null},missingInputs:[...missing,...(!listings.length?['listings con fonte']:[])]};
